INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7618039, 1233195, 179769, '<td valign="top">The shallow DOF moves your eye AWAY from the vase and toward the left side of the image....intentional?</td>', 'The shallow DOF moves your eye AWAY from the vase and toward the left side of the image....intentional?', '2019-03-08 08:15:55.000000', NULL, 1),
(7618041, 1233834, 179769, '<td valign="top">Lovely!</td>', 'Lovely!', '2019-03-08 08:16:35.000000', NULL, 1),
(7618042, 1233643, 179769, '<td valign="top">A beautiful vase in need of a bloom.</td>', 'A beautiful vase in need of a bloom.', '2019-03-08 08:17:12.000000', NULL, 1),
(7618046, 1233604, 179769, '<td valign="top">Soft focus doesn''t work here.</td>', 'Soft focus doesn''t work here.', '2019-03-08 08:24:16.000000', NULL, 1),
(7618047, 1233841, 179769, '<td valign="top">Gorgeous!</td>', 'Gorgeous!', '2019-03-08 08:25:04.000000', NULL, 1),
(7618064, 1233195, 103142, '<td valign="top">I really like the idea on this one. And the vase works great oof. But having the focus point way off on the left isn''t really working for me. It makes it look crowded and a bit uncomfortable in the crop. Once the crop is uncomfortable, you start looking around more and notice the thing in the upper right and perhaps another vase or something straight up above. If the focus point had been more of one of the central flowers (even if it was a smaller one, it would have kept my eye from roaming.<br/> <br/>Seems like it could have been a 7-8 with small tweaks, but ended up as a 5 as is.</td>', 'I really like the idea on this one. And the vase works great oof. But having the focus point way off on the left isn''t really working for me. It makes it look crowded and a bit uncomfortable in the crop. Once the crop is uncomfortable, you start looking around more and notice the thing in the upper right and perhaps another vase or something straight up above. If the focus point had been more of one of the central flowers (even if it was a smaller one, it would have kept my eye from roaming. Seems like it could have been a 7-8 with small tweaks, but ended up as a 5 as is.', '2019-03-08 10:35:31.000000', NULL, 1),
(7618065, 1233809, 103142, '<td valign="top">Seems a little too sharpened and too bright. Imo, it would have been more effective toned done in the saturation and contrast. It just appears to be shouting a bit.</td>', 'Seems a little too sharpened and too bright. Imo, it would have been more effective toned done in the saturation and contrast. It just appears to be shouting a bit.', '2019-03-08 10:36:46.000000', NULL, 1),
(7618066, 1233196, 103142, '<td valign="top">Nice background... How did you achieve it?</td>', 'Nice background... How did you achieve it?', '2019-03-08 10:37:18.000000', NULL, 1),
(7618067, 1233083, 103142, '<td valign="top">Is it a Neat photo? I like your toning. I would have liked it a bit away from the wall so that the wall didn''t have so much texture -- but only because the texture on the vase is simply yummy! The lighting, the shadow, the toning are all wonderful. 7 as is. 8 or so with less texture on the background. Higher would have needed some sort of emotional connection. Not quite sure how to do that with a vase. :)</td>', 'Is it a Neat photo? I like your toning. I would have liked it a bit away from the wall so that the wall didn''t have so much texture -- but only because the texture on the vase is simply yummy! The lighting, the shadow, the toning are all wonderful. 7 as is. 8 or so with less texture on the background. Higher would have needed some sort of emotional connection. Not quite sure how to do that with a vase. :)', '2019-03-08 10:43:51.000000', NULL, 1),
(7618068, 1233521, 103142, '<td valign="top">Love the cat. Interesting vase. Wondering if a bit of perspective correction would have helped. Everything else is so symmetric, the skew on the right just keeps drawing my eye.</td>', 'Love the cat. Interesting vase. Wondering if a bit of perspective correction would have helped. Everything else is so symmetric, the skew on the right just keeps drawing my eye.', '2019-03-08 10:48:27.000000', NULL, 1),
